using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text.Json;
using System.Text.RegularExpressions;

using Dotenvx.Interop.DotenvxJs.Helpers;

namespace Dotenvx.Help;

/// <summary>One (term, description) row of a commander help list.</summary>
public sealed record HelpRow(string Term, string Description);

/// <summary>What commander's Help class computed for one command (generated by scripts/gen-help-spec.js).</summary>
public sealed class HelpSpec
{
    public string Name { get; set; } = "";
    public string Usage { get; set; } = "";
    public bool AllowExcessArguments { get; set; } = true;
    public int ArgumentCount { get; set; }
    public bool LastArgumentVariadic { get; set; }
    public string Description { get; set; } = "";
    public int PadWidth { get; set; }
    public List<HelpRow> Arguments { get; set; } = [];
    public List<HelpRow> Options { get; set; } = [];
    public List<OptionRegistration> Registrations { get; set; } = [];
    public List<HelpRow> Commands { get; set; } = [];
    public bool Hidden { get; set; }
    public string After { get; set; } = "";
    public List<HelpSpec> Children { get; set; } = [];
}

/// <remarks>
/// Reference source: commander's Help.formatHelp / wrap (bundled in @dotenvx/tooling) plus the helpInformation overrides of
/// dotenvx/src/cli/dotenvx.js and cli/commands/ext.js. The rows (terms, descriptions, pad width) come from
/// <c>help-spec.json</c>, dumped from the real command tree by <c>node scripts/gen-help-spec.js</c>; this class only
/// lays them out with commander's own wrapping algorithm, so `--help` is byte-identical to Node's at any terminal width.
/// </remarks>
public static class CommanderHelp
{
    private const int MinColumnWidth = 40;
    private const int ItemIndent = 2;
    private const int ItemSeparatorWidth = 2;

    // JS: " \f\t\v\u00a0\u1680\u2000-\u200a\u202f\u205f\u3000\ufeff"
    private static readonly Regex PreformattedLine = new("[\n][ \f\t\v\u00a0\u1680\u2000-\u200a\u202f\u205f\u3000\ufeff]+");

    private static readonly Lazy<HelpSpec> Root = new(LoadSpec);

    /// <summary>The whole generated spec tree (the pinned upstream command tree).</summary>
    public static HelpSpec RootSpec => Root.Value;

    /// <summary>The help width: the terminal width on a TTY, else 80. Swappable for tests.</summary>
    public static Func<int> HelpWidth { get; internal set; } = DefaultHelpWidth;

    internal static void ResetToDefaults()
    {
        HelpWidth = DefaultHelpWidth;
    }

    private static int DefaultHelpWidth()
    {
        if (Console.IsOutputRedirected)
        {
            return 80;
        }

        try
        {
            int columns = Console.WindowWidth;

            return columns > 0 ? columns : 80;
        }
        catch (IOException)
        {
            return 80;
        }
    }

    private static HelpSpec LoadSpec()
    {
        using Stream stream = Assembly.GetExecutingAssembly().GetManifestResourceStream("Dotenvx.Help.help-spec.json")
                              ?? throw new InvalidOperationException("help-spec.json is not embedded");

        return JsonSerializer.Deserialize<HelpSpec>(stream, new JsonSerializerOptions { PropertyNameCaseInsensitive = true })!;
    }

    /// <summary>The spec of the command at <paramref name="path" /> (names below the root), or null when upstream has no such command.</summary>
    public static HelpSpec? Find(IReadOnlyList<string> path)
    {
        HelpSpec current = Root.Value;
        foreach (string name in path)
        {
            HelpSpec? next = current.Children.FirstOrDefault(child => child.Name == name);
            if (next is null)
            {
                return null;
            }

            current = next;
        }

        return current;
    }

    /// <summary>`command.helpInformation()` including the root and ext overrides.</summary>
    public static string Render(HelpSpec spec, bool isRoot)
    {
        string text = FormatHelp(spec, HelpWidth());
        if (!isRoot && spec.Name != "ext")
        {
            return text;
        }

        List<string> lines = [.. text.Split('\n')];
        HelpTextFilters.RemoveDynamicHelpSection(lines);
        if (!isRoot)
        {
            return string.Join("\n", lines);
        }

        HelpTextFilters.RemoveOptionsHelpParts(lines);

        return string.Join("\n", lines.Where(line =>
            !line.Contains("DEPRECATED") && !line.Contains("help [command]") && !line.Contains("🔌 extensions")));
    }

    private static string FormatHelp(HelpSpec spec, int helpWidth)
    {
        int termWidth = spec.PadWidth;

        string Item(HelpRow row)
        {
            if (row.Description.Length == 0)
            {
                return row.Term;
            }

            string text = row.Term.PadRight(termWidth + ItemSeparatorWidth) + row.Description;

            return Wrap(text, helpWidth - ItemIndent, termWidth + ItemSeparatorWidth);
        }

        string Indent(IEnumerable<string> items)
        {
            return Regex.Replace(string.Join("\n", items), "^", new string(' ', ItemIndent), RegexOptions.Multiline);
        }

        var output = new List<string> { $"Usage: {spec.Usage}", "" };
        if (spec.Description.Length > 0)
        {
            output.Add(Wrap(spec.Description, helpWidth, 0));
            output.Add("");
        }

        if (spec.Arguments.Count > 0)
        {
            output.AddRange(["Arguments:", Indent(spec.Arguments.Select(Item)), ""]);
        }

        if (spec.Options.Count > 0)
        {
            output.AddRange(["Options:", Indent(spec.Options.Select(Item)), ""]);
        }

        if (spec.Commands.Count > 0)
        {
            output.AddRange(["Commands:", Indent(spec.Commands.Select(Item)), ""]);
        }

        return string.Join("\n", output);
    }

    /// <summary>commander's Help.wrap: wraps <paramref name="str" /> at <paramref name="width" />, indenting continuation lines by <paramref name="indent" />.</summary>
    public static string Wrap(string str, int width, int indent)
    {
        if (PreformattedLine.IsMatch(str))
        {
            return str;
        }

        int columnWidth = width - indent;
        if (columnWidth < MinColumnWidth)
        {
            return str;
        }

        string leading = str[..indent];
        string columnText = str[indent..].Replace("\r\n", "\n");
        string spaces = new(' ', indent);
        // JS `\s` also covers the BOM (.NET's does not); JS `.` excludes line terminators; JS `$` is the end of input only
        string breaks = @"\s" + (char)0xFEFF + (char)0x200B;
        string lineTerminators = @"\n\r" + (char)0x2028 + (char)0x2029;
        var chunkPattern = new Regex(
            $@"\n|[^{lineTerminators}]{{1,{columnWidth - 1}}}([{breaks}]|\z)|[^{breaks}]+?([{breaks}]|\z)");
        MatchCollection matches = chunkPattern.Matches(columnText);

        return leading + string.Join("\n", matches.Select((match, index) =>
            match.Value == "\n" ? "" : (index > 0 ? spaces : "") + TrimEndJs(match.Value)));
    }

    private static string TrimEndJs(string value)
    {
        return value.TrimEnd().TrimEnd((char)0xFEFF).TrimEnd();
    }
}
